{
  "schemaVersion": "0.2",
  "slug": "title-bar",
  "name": "TitleBar",
  "family": "B",
  "status": "experimental",
  "purpose": "Official Navigation sidebar brand header: logo + title + subtitle with default home activation and brand chrome (no select / no context menu). Mount in Navigation header / #header — not AppShell header (that is NavigationTitle).",
  "scenarios": [
    "Put product logo + name + tagline above the Navigation destination list in the sidebar rail",
    "Collapse the tablet rail so only the mark (or letter fallback) remains",
    "Activate the brand to return home via homeHref or onBrandClick without consumer chrome CSS"
  ],
  "props": {
    "title": {
      "type": "string",
      "required": true,
      "description": "Product name; accessible name of the brand control."
    },
    "subtitle": {
      "type": "string",
      "required": false,
      "description": "Short tagline; hidden when density is compact or Navigation is collapsed."
    },
    "logoSrc": {
      "type": "string",
      "required": false,
      "description": "Raster logo URL (png/jpeg/webp). Prefer logo / #logo for SVG or Icon."
    },
    "logoAlt": {
      "type": "string",
      "required": false,
      "description": "Alt text for logoSrc; defaults to title."
    },
    "logo": {
      "type": "node",
      "required": false,
      "description": "Custom mark (SVG/Icon). Wins over logoSrc. Vue: #logo slot."
    },
    "density": {
      "type": "enum",
      "required": false,
      "description": "default shows title/subtitle; compact is mark-only. Collapsed Navigation also hides text via CSS.",
      "values": ["default", "compact"],
      "default": "default"
    },
    "homeHref": {
      "type": "string",
      "required": false,
      "description": "Home URL. When set, root is an anchor. Click priority: onBrandClick first; link navigates unless preventDefault."
    },
    "onBrandClick": {
      "type": "event",
      "required": false,
      "description": "Brand activation (SPA home / tab reset). Vue: brand-click. Runs before homeHref navigation.",
      "payload": "(event) => void"
    },
    "brandInteractive": {
      "type": "boolean",
      "required": false,
      "description": "When false, static chrome (no link / keyboard activation).",
      "default": true
    },
    "preventContextMenu": {
      "type": "boolean",
      "required": false,
      "description": "Suppress contextmenu on brand chrome.",
      "default": true
    },
    "userSelectNone": {
      "type": "boolean",
      "required": false,
      "description": "Apply user-select: none.",
      "default": true
    },
    "homeLabel": {
      "type": "string",
      "required": false,
      "description": "Accessible name override; defaults to title."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [
    {
      "name": "density",
      "values": ["default", "compact"],
      "default": "default",
      "description": "Full brand row vs mark-only."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Expanded brand row with title and optional subtitle."
    },
    {
      "name": "compact",
      "description": "Mark-only density (prop or collapsed Navigation rail)."
    }
  ],
  "composition": {
    "allowedParents": ["navigation", "app-shell", "page"],
    "allowedChildren": ["brand-mark", "icon", "text"],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not mount TitleBar on the compact TabBar or duplicate logo+title+subtitle beside Navigation items — Navigation hides header below 48rem by design.",
    "Do not put TitleBar in AppShell header; that slot is NavigationTitle (stack chrome).",
    "Do not hand-roll user-select / contextmenu overrides for brand chrome — use the defaults or opt-out props.",
    "Do not invent a consumer cu- TitleBar pretending to be a library export."
  ],
  "a11y": {
    "role": "button or link",
    "keyboard": [
      "Enter/Space activate when interactive without homeHref",
      "Tab focuses the interactive brand control"
    ],
    "focus": "Interactive brand is one tab stop; static mode is not focusable.",
    "labeling": "Accessible name is homeLabel or title; compact mode keeps title via aria-label / title tooltip.",
    "wcag": ["1.3.1", "2.1.1", "2.4.4", "4.1.2"]
  },
  "responsive": {
    "strategy": "TitleBar itself is not breakpoint-aware. Visibility is owned by Navigation: sidebar/rail shows __header; compact TabBar hides it (formal DoD).",
    "breakpoints": {
      "compact": "Must not present TitleBar — Navigation __header is display:none.",
      "medium": "Visible in Navigation header; collapsed rail hides text via CSS.",
      "large": "Visible in Navigation header with full title/subtitle."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical flex row; text ellipsis follows document direction.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "title-bar",
    "states": ["default", "compact"],
    "intents": ["navigate", "show-brand"]
  },
  "mechanics": "Export TitleBar and place it in Navigation header / #header — not AppShell header (that is NavigationTitle). Defaults: brandInteractive true, preventContextMenu true, userSelectNone true, density default. Click priority: onBrandClick (Vue brand-click) then homeHref unless preventDefault. Host chrome row (Navigation __header) uses min-block-size calc(var(--cu-control-size-active) + 2 * var(--cu-space-1)) to align with NavigationTitle. Compact TabBar must not show this — Navigation hides __header below 48rem.",
  "usage": [
    "Import TitleBar from @chameleon-ui/components-react or the React/Vue umbrella.",
    "Pass as Navigation header (React) or #header slot (Vue) — never AppShell header.",
    "Bind onBrandClick / brand-click to reset the home tab, and/or set homeHref.",
    "Optional logo slot/node for SVG; otherwise logoSrc (BrandMark) or letter fallback."
  ],
  "exports": [
    {
      "name": "TitleBar",
      "kind": "component",
      "signature": "function TitleBar(props: TitleBarProps): JSX.Element",
      "description": "Sidebar brand header for Navigation header / #header."
    },
    {
      "name": "TitleBarProps",
      "kind": "type",
      "signature": "interface TitleBarProps",
      "description": "Public props including density, homeHref, and brand chrome defaults."
    },
    {
      "name": "TitleBarDensity",
      "kind": "type",
      "signature": "'default' | 'compact'",
      "description": "Expanded vs mark-only density."
    }
  ]
}

/*
 * TitleBar — Navigation sidebar brand header (logo + title + subtitle).
 * Mount in Navigation `header` / `#header`. Compact TabBar hides that slot
 * (`.cu-navigation__header { display: none }` below 48rem) — DoD: never
 * duplicate this structure on the mobile TabBar.
 */
.cu-title-bar {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: var(--cu-space-2);
  min-inline-size: 0;
  max-inline-size: 100%;
  padding: 0;
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: start;
  text-decoration: none;
}

.cu-title-bar--no-select {
  -webkit-user-select: none;
  user-select: none;
}

.cu-title-bar--interactive {
  cursor: pointer;
}

.cu-title-bar--interactive:focus-visible {
  outline: 2px solid var(--cu-color-palette-brand);
  outline-offset: 2px;
  border-radius: var(--cu-radius-sm);
}

.cu-title-bar__mark {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  min-inline-size: 1.25rem;
  min-block-size: 1.25rem;
}

.cu-title-bar__letter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: 1.75rem;
  block-size: 1.75rem;
  border-radius: var(--cu-radius-sm);
  background: color-mix(in srgb, var(--cu-color-palette-brand) 14%, transparent);
  color: var(--cu-color-palette-brand);
  font-size: 0.875rem;
  font-weight: var(--cu-typography-weight-bold, 700);
  line-height: 1;
}

.cu-title-bar--compact .cu-title-bar__letter,
.cu-navigation--collapsed .cu-title-bar .cu-title-bar__letter {
  inline-size: 1.25rem;
  block-size: 1.25rem;
  font-size: 0.75rem;
}

.cu-title-bar__text {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  min-inline-size: 0;
}

.cu-title-bar__title,
.cu-title-bar__subtitle {
  min-inline-size: 0;
  max-inline-size: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cu-title-bar__title {
  font-size: 1rem;
  font-weight: var(--cu-typography-weight-semibold, 600);
  line-height: 1.25;
  color: var(--cu-color-fg-default);
}

.cu-title-bar__subtitle {
  font-size: 0.75rem;
  line-height: 1.3;
  color: var(--cu-color-fg-muted, var(--cu-color-fg-default));
  opacity: 0.72;
}

/* Prop density + Navigation collapsed rail — mark only. */
.cu-title-bar--compact .cu-title-bar__text,
.cu-navigation--collapsed .cu-title-bar .cu-title-bar__text {
  display: none;
}

.cu-title-bar--compact,
.cu-navigation--collapsed .cu-title-bar {
  justify-content: center;
}

.cu-navigation--collapsed .cu-title-bar .cu-brand-mark--md {
  block-size: 1.25rem;
}

import type { KeyboardEvent as ReactKeyboardEvent, MouseEvent as ReactMouseEvent, ReactNode } from 'react'
import { BrandMark } from '../brand-mark/BrandMark.js'
import './styles.css'

export type TitleBarDensity = 'default' | 'compact'

export interface TitleBarProps {
  /** Product name — accessible name of the brand control. */
  title: string
  /** Short tagline; hidden when density is compact (or Navigation rail is collapsed). */
  subtitle?: string
  /** Raster logo (png / jpeg / webp). Prefer `logo` for SVG / Icon / arbitrary mark. */
  logoSrc?: string
  /** Alt text for `logoSrc`. Defaults to `title`. */
  logoAlt?: string
  /** Custom mark node (SVG / Icon). Wins over `logoSrc` when provided. */
  logo?: ReactNode
  /**
   * Density. `compact` shows the mark only (letter fallback when no logo).
   * Inside a collapsed Navigation rail, CSS also hides the text block.
   */
  density?: TitleBarDensity
  /**
   * Home URL. When set and interactive, the root is an `<a>`.
   * Click priority: `onBrandClick` runs first; the link navigates unless the
   * handler calls `preventDefault()`.
   */
  homeHref?: string
  /** Brand activation handler (home / reset). Prefer this for SPA tab reset. */
  onBrandClick?: (event: ReactMouseEvent | ReactKeyboardEvent) => void
  /** When false, chrome is static (no link, no keyboard activation). Default true. */
  brandInteractive?: boolean
  /** Suppress the context menu on brand chrome. Default true. */
  preventContextMenu?: boolean
  /** Apply `user-select: none`. Default true. */
  userSelectNone?: boolean
  /** Override accessible name (defaults to `title`). */
  homeLabel?: string
  className?: string
}

function letterFallback(title: string) {
  const letter = Array.from(title.trim())[0] ?? '?'
  return (
    <span className="cu-title-bar__letter" aria-hidden="true">
      {letter}
    </span>
  )
}

export function TitleBar({
  title,
  subtitle,
  logoSrc,
  logoAlt,
  logo,
  density = 'default',
  homeHref,
  onBrandClick,
  brandInteractive = true,
  preventContextMenu = true,
  userSelectNone = true,
  homeLabel,
  className,
}: TitleBarProps) {
  const compact = density === 'compact'
  const classes = [
    'cu-title-bar',
    compact && 'cu-title-bar--compact',
    brandInteractive && 'cu-title-bar--interactive',
    userSelectNone && 'cu-title-bar--no-select',
    className,
  ]
    .filter(Boolean)
    .join(' ')

  const accessibleName = homeLabel ?? title
  const mark =
    logo ??
    (logoSrc ? (
      <BrandMark src={logoSrc} alt={logoAlt || title} size={compact ? 'sm' : 'md'} />
    ) : (
      letterFallback(title)
    ))

  const body = (
    <>
      <span className="cu-title-bar__mark">{mark}</span>
      <span className="cu-title-bar__text">
        <span className="cu-title-bar__title">{title}</span>
        {subtitle ? <span className="cu-title-bar__subtitle">{subtitle}</span> : null}
      </span>
    </>
  )

  function onContextMenu(event: ReactMouseEvent) {
    if (preventContextMenu) event.preventDefault()
  }

  function onActivate(event: ReactMouseEvent | ReactKeyboardEvent) {
    onBrandClick?.(event)
  }

  function onKeyDown(event: ReactKeyboardEvent) {
    if (!brandInteractive) return
    if (event.key !== 'Enter' && event.key !== ' ') return
    event.preventDefault()
    onActivate(event)
  }

  if (!brandInteractive) {
    return (
      <div
        className={classes}
        data-density={density}
        data-interactive="false"
        data-ai-role="title-bar"
        data-ai-intent="navigate"
        data-ai-state={compact ? 'compact' : 'default'}
        onContextMenu={onContextMenu}
      >
        {body}
      </div>
    )
  }

  if (homeHref) {
    return (
      <a
        className={classes}
        href={homeHref}
        aria-label={accessibleName}
        title={compact ? title : undefined}
        data-density={density}
        data-interactive="true"
        data-ai-role="title-bar"
        data-ai-intent="navigate"
        data-ai-state={compact ? 'compact' : 'default'}
        onClick={onActivate}
        onKeyDown={onKeyDown}
        onContextMenu={onContextMenu}
      >
        {body}
      </a>
    )
  }

  return (
    <div
      className={classes}
      role="button"
      tabIndex={0}
      aria-label={accessibleName}
      title={compact ? title : undefined}
      data-density={density}
      data-interactive="true"
      data-ai-role="title-bar"
      data-ai-intent="navigate"
      data-ai-state={compact ? 'compact' : 'default'}
      onClick={onActivate}
      onKeyDown={onKeyDown}
      onContextMenu={onContextMenu}
    >
      {body}
    </div>
  )
}
